 // ── the icon vocabulary ────────────────────────────────────────────────
// Each glyph is authored in a 100×100 box and scaled by the caller.
// Kinds: sun, moon, cloud, partly, cloudmoon, storm, rain, sunset,
// sunrise. A `script { }` block is plain TypeScript; these helpers are
// callable from any draw() in the file.
// ── the two drawn skies ────────────────────────────────────────────────
// Functions rather than classes, because a sky is drawn at two sizes: the
// full page, and a 92px list row. Both are the same picture scaled by its
// own box, and both are worth drawing — a row's sky is the thing that
// tells you at a glance which cities are clear and which are overcast.
function artSunnySky(d, w, h) {
    const g = d.createLinearGradient(0, 0, 0, h);
    g.addColorStop(0, "#2E7FD0");
    g.addColorStop(0.45, "#5AA2E0");
    g.addColorStop(1, "#9CC6E8");
    d.fillStyle = g;
    d.fillRect(0, 0, w, h);
    // the sun: a layered radial glow, high right. The radius is clamped
    // because a negative radial radius throws — and a drawn component
    // that throws takes the whole boot with it, which is too sharp an
    // edge for the zero-width moment before a box has been measured.
    const sx = w * 0.82, sy = h * 0.10;
    const glow = d.createRadialGradient(sx, sy, 0, sx, sy, Math.max(0, w * 0.55));
    glow.addColorStop(0, "rgba(255,244,214,0.95)");
    glow.addColorStop(0.12, "rgba(255,236,180,0.55)");
    glow.addColorStop(0.35, "rgba(255,236,180,0.16)");
    glow.addColorStop(1, "rgba(255,236,180,0)");
    d.fillStyle = glow;
    d.fillRect(0, 0, w, h);
}
function artNightSky(d, w, h) {
    const g = d.createLinearGradient(0, 0, 0, h);
    g.addColorStop(0, "#0A1230");
    g.addColorStop(0.55, "#16244C");
    g.addColorStop(1, "#2A3A66");
    d.fillStyle = g;
    d.fillRect(0, 0, w, h);
    // a deterministic star field: a seeded walk, so the same stars land
    // in the same places on every redraw. The count follows the area, so
    // a row gets a plausible scatter rather than the page's ninety.
    let seed = 7;
    const rnd = () => { seed = (seed * 16807) % 2147483647; return seed / 2147483647; };
    const n = Math.max(12, Math.round(90 * (w * h) / (390 * 850)));
    for (let i = 0; i < n; i++) {
        const x = rnd() * w, y = rnd() * h * 0.7, r = 0.4 + rnd() * 1.1;
        d.globalAlpha = 0.25 + rnd() * 0.65;
        d.fillStyle = "#DDE6F5";
        d.beginPath();
        d.arc(x, y, r, 0, Math.PI * 2);
        d.fill();
    }
    d.globalAlpha = 1;
}
function artCloudPath(d, cx, cy, s) {
    // a cloud is three puffs on a flat-bottomed capsule
    d.beginPath();
    d.arc(cx - 22 * s, cy + 6 * s, 14 * s, Math.PI * 0.5, Math.PI * 1.5);
    d.arc(cx - 8 * s, cy - 8 * s, 16 * s, Math.PI * 0.8, Math.PI * 1.9);
    d.arc(cx + 12 * s, cy - 4 * s, 13 * s, Math.PI * 1.1, Math.PI * 1.98);
    d.arc(cx + 22 * s, cy + 6 * s, 14 * s, Math.PI * 1.5, Math.PI * 0.5);
    d.closePath();
}
function artSun(d, cx, cy, r) {
    d.fillStyle = "#FFD34D";
    for (let i = 0; i < 8; i++) {
        const a = (i / 8) * Math.PI * 2;
        d.save();
        d.translate(cx, cy);
        d.rotate(a);
        d.beginPath();
        d.roundRect(r * 1.35, -r * 0.14, r * 0.55, r * 0.28, r * 0.14);
        d.fill();
        d.restore();
    }
    d.beginPath();
    d.arc(cx, cy, r, 0, Math.PI * 2);
    d.fill();
}
function artMoon(d, cx, cy, r, color) {
    // crescent: a full disc minus an offset disc, via a composite
    d.save();
    d.beginPath();
    d.arc(cx, cy, r, 0, Math.PI * 2);
    d.fillStyle = color;
    d.fill();
    d.globalCompositeOperation = "destination-out";
    d.beginPath();
    d.arc(cx + r * 0.62, cy - r * 0.3, r * 0.86, 0, Math.PI * 2);
    d.fill();
    d.restore();
}
function artIcon(d, kind, w, h) {
    const s = Math.min(w, h) / 100;
    d.save();
    d.scale(s, s);
    const cloudColor = "#F4F7FB";
    if (kind == "sun")
        artSun(d, 50, 50, 26);
    else if (kind == "moon")
        artMoon(d, 50, 50, 30, "#F4F7FB");
    else if (kind == "cloud") {
        d.fillStyle = cloudColor;
        artCloudPath(d, 50, 56, 1.15);
        d.fill();
    }
    else if (kind == "partly") {
        artSun(d, 36, 34, 17);
        d.fillStyle = cloudColor;
        artCloudPath(d, 56, 64, 1.0);
        d.fill();
    }
    else if (kind == "cloudmoon") {
        artMoon(d, 36, 34, 18, "#E8ECF4");
        d.fillStyle = cloudColor;
        artCloudPath(d, 56, 64, 1.0);
        d.fill();
    }
    else if (kind == "storm") {
        d.fillStyle = cloudColor;
        artCloudPath(d, 50, 46, 1.05);
        d.fill();
        d.fillStyle = "#FFD34D";
        d.beginPath();
        d.moveTo(52, 56);
        d.lineTo(40, 78);
        d.lineTo(50, 78);
        d.lineTo(44, 96);
        d.lineTo(64, 70);
        d.lineTo(53, 70);
        d.lineTo(60, 56);
        d.closePath();
        d.fill();
    }
    else if (kind == "rain") {
        d.fillStyle = cloudColor;
        artCloudPath(d, 50, 44, 1.05);
        d.fill();
        d.strokeStyle = "#7FB2F2";
        d.lineWidth = 6;
        d.lineCap = "round";
        for (let i = 0; i < 3; i++) {
            d.beginPath();
            d.moveTo(34 + i * 16, 66);
            d.lineTo(28 + i * 16, 86);
            d.stroke();
        }
    }
    else if (kind == "sunset" || kind == "sunrise") {
        // a half sun on a horizon, with an arrow up or down
        d.fillStyle = "#FFD34D";
        d.beginPath();
        d.arc(50, 58, 20, Math.PI, 0);
        d.closePath();
        d.fill();
        d.strokeStyle = "#F4F7FB";
        d.lineWidth = 5;
        d.lineCap = "round";
        d.beginPath();
        d.moveTo(16, 62);
        d.lineTo(84, 62);
        d.stroke();
        d.beginPath();
        const up = kind == "sunrise";
        d.moveTo(50, up ? 40 : 22);
        d.lineTo(50, up ? 22 : 40);
        d.moveTo(42, up ? 30 : 32);
        d.lineTo(50, up ? 22 : 40);
        d.lineTo(58, up ? 30 : 32);
        d.stroke();
    }
    d.restore();
}
;
// ── the numbers more than one place must agree on ──────────────────────
// A `script { }` block is plain TypeScript; its top-level constants and
// functions are readable from any `{ }` body in the file. Everything
// that appears only once stays a literal where it is used.
const SMALL_CARD_H = 176; // natural height of a one-slot card
const CONDENSE_SPAN = 120; // scroll distance over which the hero condenses
const EDGE_SLACK = 160; // how far past the viewport a sky reaches
const LIST_TOP = 62; // where the phone list's rows begin (below search)
const ROW_H = 92; // a list row at rest
const ROW_GAP = 10; // the air between two rows
const HERO_H = 268; // the opened row: name, temperature, condition
const LIST_TAIL = 40; // breathing room after the last row
const SIDEBAR_W = 340; // the desktop city list, and where the content starts
// ── a debug arm for watching the transition ────────────────────────────
// `?slow` runs every spring ten times slower; `?slow=N` picks the factor.
// The motion is unchanged — only its clock is stretched — because the
// damping ratio ζ = c / 2√(km) is what shapes a spring, and holding it
// fixed while slowing by N means k/N² and c/N. The rest threshold scales
// too (1/N): velocities are N times smaller at the end, so an unscaled
// epsilon would call the arrival early and cut the tail off.
const SLOW = (() => {
    if (typeof location == "undefined")
        return 1;
    // the lookahead matters: without it `?slowland` matches this too, and
    // the spring silently runs ten times slower than the reader asked for
    const m = location.search.match(/[?&]slow(?:=(\d+))?(?![a-z])/);
    if (m == null)
        return 1;
    return m[1] == null ? 10 : Math.max(1, Number(m[1]));
})();
function slowK(k) { return k / (SLOW * SLOW); }
function slowC(c) { return c / SLOW; }
function slowEps(e) { return e / SLOW; }
function fmtTemp(n) { return "" + Math.round(n) + "°"; }
/** Read a value between two ends. Every travelling element in the city
 *  view is one of these — which is why a position and a font size can
 *  animate together without a keyframe anywhere. */
function lerp(a, b, t) { return a + (b - a) * t; }
/** 0 until `v` passes `start`, then rising at `speed` — an opacity that
 *  arrives partway through a transition. (Anything past 1 renders as 1.) */
function fadeIn(v, start, speed) {
    return Math.max(0, (v - start) * speed);
}
/** 1 at rest, falling at `speed` as `v` rises — an opacity that leaves
 *  early in a transition. */
function fadeOut(v, speed) {
    return Math.max(0, 1 - v * speed);
}
/** One instant, read at a place: `ms` is the shared clock, `tzMin` the
 *  place's offset from UTC in minutes. Wall-clock arithmetic only. */
function localTime(ms, tzMin) {
    if (ms <= 0)
        return "";
    const d = new Date(ms + tzMin * 60000);
    let h = d.getUTCHours();
    const m = d.getUTCMinutes();
    const ap = h < 12 ? "AM" : "PM";
    h = h % 12;
    if (h == 0)
        h = 12;
    return "" + h + ":" + (m < 10 ? "0" : "") + m + " " + ap;
} /*$b*/ return { artSunnySky, artNightSky, artCloudPath, artSun, artMoon, artIcon, SMALL_CARD_H, CONDENSE_SPAN, EDGE_SLACK, LIST_TOP, ROW_H, ROW_GAP, HERO_H, LIST_TAIL, SIDEBAR_W, SLOW, slowK, slowC, slowEps, fmtTemp, lerp, fadeIn, fadeOut, localTime };

methods.body:
const i = this.root.cities.findIndex((c) => c.id == id)
if (i >= 0) this.cityIndex = i
// a fresh city reads from the top of its page
this.deskUI.content.scrollTo(0)

if (this.root.shown.value == null) return 0
const i = this.root.shown.value.rows.findIndex((r) => r.id == id)
return Math.max(0, i) * (ROW_H + ROW_GAP)

const past = (raw > 0 && this.root.cityIndex == 0)
    || (raw < 0 && this.root.cityIndex >= this.root.cities.length - 1)
if (!past) return raw
const limit = this.root.hostWidth / 2
const d = Math.abs(raw)
return (raw < 0 ? -1 : 1) * d * limit / (d + limit)

this.cityIndex = i
this.openId = this.root.cities[i].id
// the arriving city reads from its own top — the page is the document
// now, and the city's top is the document's top once open has landed
this.root.scrollTo(0)

if (!this.root.dragging) return
this.dragging = false
this.swipeTo = 0
if (canceled) return
const moved = this.root.swipeX
const n = this.root.cities.length
// past a third of the screen the page turns — and swipeX is rebased
// by a screen-width, so the new current page carries on from exactly
// where the arriving one was, with no jump to hide
if (moved < -this.root.hostWidth / 3 && this.root.cityIndex < n - 1) {
    this.pageTo(this.root.cityIndex + 1)
    this.swipeX = this.root.swipeX + this.root.hostWidth
} else if (moved > this.root.hostWidth / 3 && this.root.cityIndex > 0) {
    this.pageTo(this.root.cityIndex - 1)
    this.swipeX = this.root.swipeX - this.root.hostWidth
}

const i = this.root.cityIndex + dir
if (i < 0 || i >= this.root.cities.length) return
this.pageTo(i)
// synthesize the state a completed swipe rebases into — the new page
// a screen-width out, springing home — so a tap on the chevron reads
// as exactly the motion a swipe does. Relative, exactly as the rebase
// above is: a second tap while the first is still travelling must
// carry on from where the pages are, not restage them from scratch.
// start() wakes the spring: its target (0) has not changed, only the
// value was displaced.
this.swipeX = this.root.swipeX + (dir > 0 ? this.root.hostWidth : -this.root.hostWidth)
this.swipeTo = 0
this.swipeSpring.start()
